@Override
public Page<MemberTeamDto> searchPage(MemberSearchCondition cond,
                                      Pageable pageable) {
    JPQLQuery<MemberTeamDto> query = from(member)
            .leftJoin(member.team, team)
            .where(usernameEq(cond.getUsername()),
                   ageBetween(cond.getAgeGoe(), cond.getAgeLoe()))
            .select(new QMemberTeamDto(
                    member.id, member.username, member.age,
                    team.id, team.name));

    JPQLQuery<MemberTeamDto> paged =
            getQuerydsl().applyPagination(pageable, query);

    List<MemberTeamDto> content = paged.fetch();
    long total = query.fetchCount();

    return new PageImpl<>(content, pageable, total);
}

@Test
@Transactional
void 페이징() {
    em.clear();
    MemberSearchCondition cond = new MemberSearchCondition();
    cond.setAgeGoe(20);

    Page<MemberTeamDto> page = memberRepository.searchPage(
            cond, PageRequest.of(0, 3, Sort.by(Sort.Direction.DESC, "age")));
    System.out.println("내용: " + page.getContent().size());
    System.out.println("전체: " + page.getTotalElements());
}

