@Override
public Page<TeamStat> statsPage(Pageable pageable) {
    JPQLQuery<TeamStat> query = from(member)
            .join(member.team, team)
            .groupBy(team.name)
            .select(new QTeamStat(team.name, member.count(),
                    member.age.avg()));

    List<TeamStat> content =
            getQuerydsl().applyPagination(pageable, query).fetch();
    long total = query.fetchCount();

    return new PageImpl<>(content, pageable, total);
}

