@Override
public Page<MemberTeamDto> searchPageV2(MemberSearchCondition cond,
                                        Pageable pageable) {
    JPQLQuery<MemberTeamDto> query = from(member)
            .leftJoin(member.team, team)
            .where(ageBetween(cond.getAgeGoe(), cond.getAgeLoe()))
            .select(new QMemberTeamDto(...));

    List<MemberTeamDto> content =
            getQuerydsl().applyPagination(pageable, query).fetch();

    JPAQuery<Long> countQuery = new JPAQuery<>(getEntityManager())
            .select(member.count())
            .from(member)
            .where(ageBetween(cond.getAgeGoe(), cond.getAgeLoe()));

    return PageableExecutionUtils.getPage(content, pageable,
            countQuery::fetchOne);
}

